import { Fragment } from 'react';
import type { ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './timeline.css';

/**
 * B41 · Timeline — one job: state the ordered HISTORY of ONE record, with
 * the gaps visible. It is NOT B9 ActivityList, which is a live, flat feed
 * answering "what needs me", newest first, across many records. A Timeline
 * is one record's life — oldest-first or newest-first as the caller renders
 * it — and it shows what has NOT happened yet as well as what has, which is
 * why `pending` is a first-class tone rather than an absent row. A real
 * <ol> carries the order, so assistive tech announces position for free.
 */
export type TimelineTone = 'done' | 'pending' | 'bad';

export interface TimelineItem {
  id: string;
  /** Absolute display time, e.g. "24 JUL · 14:28". */
  time: string;
  /** Full machine timestamp for <time dateTime>. */
  dateTime?: string;
  title: string;
  /** One sentence. Two is a record page. */
  body?: ReactNode;
  /** Who did it — mono, under the body. */
  actor?: string;
  tone?: TimelineTone;
  /** Mono uppercase day divider rendered ABOVE this item. */
  group?: string;
}

export interface TimelineProps {
  items: TimelineItem[];
  className?: string;
}

/* C5 · a coloured dot is colour-only meaning, so every row says its tone
   in words too — and says it BEFORE the title, the way a reader scanning
   the rail sees the marker before the text. */
const TONE_WORD: Record<TimelineTone, string> = {
  done: 'Completed',
  pending: 'Not started',
  bad: 'Failed',
};

export function Timeline({ items, className }: TimelineProps) {
  return (
    <ol className={cx('sv-timeline', className)}>
      {items.map((item) => {
        const tone = item.tone ?? 'done';
        return (
          <Fragment key={item.id}>
            {item.group && (
              /* The day divider labels the rows below it; it is not a step
                 in the history, so it stays out of the <ol>'s count. */
              <li className="sv-timeline__day sv-mono" role="presentation">
                {item.group}
              </li>
            )}
            <li className="sv-timeline__item">
              <span
                className={cx('sv-timeline__dot', `sv-timeline__dot--${tone}`)}
                aria-hidden="true"
              />
              <time
                className="sv-timeline__time sv-mono"
                dateTime={item.dateTime}
                title={item.dateTime}
              >
                {item.time}
              </time>
              <p className="sv-timeline__title">
                <span className="sv-visually-hidden">{TONE_WORD[tone]}. </span>
                {item.title}
              </p>
              {item.body && <p className="sv-timeline__body">{item.body}</p>}
              {item.actor && <p className="sv-timeline__actor sv-mono">{item.actor}</p>}
            </li>
          </Fragment>
        );
      })}
    </ol>
  );
}

/* B41 · Timeline — the rail carries the rhythm, so there are no hairlines. */

@layer sv-components {
  .sv-timeline {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* 20px rail column + an 8px gutter. The 16px row gap is padding, not a
     flex gap, so each row's rail meets the next one and the line is
     continuous down the sequence. */
  .sv-timeline__item {
    position: relative;
    padding: 0 0 var(--sv-s4) 28px;
  }

  .sv-timeline__item:last-child {
    padding-bottom: 0;
  }

  .sv-timeline__item::before {
    content: '';
    position: absolute;
    left: 9.5px;
    top: 0;
    bottom: 0;
    width: 1px;
    background: var(--sv-line);
  }

  /* The line starts at the first marker and stops at the last, so it never
     dangles past the sequence. A day divider restarts it the same way. */
  .sv-timeline__item:first-child::before,
  .sv-timeline__day + .sv-timeline__item::before {
    top: 10px;
  }

  .sv-timeline__item:last-child::before {
    bottom: calc(100% - 10px);
  }

  /* The marker is an 11px circle whose outer 2px is a paper ring drawn as
     an INSET shadow — what reads is a 7px dot sitting on the rail rather
     than crossing it, with no elevation shadow anywhere near it. */
  .sv-timeline__dot {
    position: absolute;
    left: 4.5px;
    top: 4.5px;
    width: 11px;
    height: 11px;
    border-radius: 50%;
    box-shadow: inset 0 0 0 2px var(--sv-paper);
  }

  .sv-timeline__dot--done {
    background: var(--sv-seed);
  }

  .sv-timeline__dot--bad {
    background: var(--sv-bad);
  }

  /* Not started: the ring is the dot's ONLY affordance, so it takes the
     3:1 step, not the hairline. */
  .sv-timeline__dot--pending {
    background: var(--sv-paper);
    box-shadow: inset 0 0 0 2px var(--sv-paper), inset 0 0 0 3.5px var(--sv-field-line-strong);
  }

  /* ---- v0.9 · the rail runs down, and it is OFF until the app asks

     B41's opening line is that the rail carries the rhythm, which is
     why there are no hairlines between rows. So the rail is what moves,
     and it moves the way the sequence is read: down.

     EVERY SEGMENT DRAWS ON THE SAME FRAME. Each row owns a piece of the
     rail (the ::before, padded so it meets the next row's and the line
     is continuous), and scaling each from its own top means the whole
     rail extends downward as one — an unbroken line growing, not eight
     lines growing. The alternative was a per-row delay, which would
     produce the same picture and would be a stagger: a queue of delayed
     children is the page performing, refused here as it is refused in
     use-reveal.ts and meter-list.css.

     The dots FADE rather than scale. A dot that grows from nothing is
     the marker performing its own arrival, and B41's marker is a
     precise 11px circle whose outer 2px is a paper ring — scaling it
     would animate that ring to sub-pixel and read as a smudge on the
     way in. Opacity leaves the geometry alone on every frame.

     Posture-gated, `--sv-t-enter`, base.css's curve. A Timeline is a
     record of things that already happened; nobody clicked to make it
     appear, so it is an arrival and it is off until a product says
     otherwise. Nothing here is information: the state is in the dot's
     fill, the copy beside it and the time it carries. */
  [data-motion='on'] .sv-timeline__item::before {
    transform-origin: center top;
    animation: sv-timeline-rail var(--sv-t-enter) cubic-bezier(0.215, 0.61, 0.355, 1);
  }

  [data-motion='on'] .sv-timeline__dot {
    animation: sv-timeline-dot var(--sv-t-enter) cubic-bezier(0.215, 0.61, 0.355, 1);
  }

  @keyframes sv-timeline-rail {
    from {
      transform: scaleY(0);
    }
  }

  @keyframes sv-timeline-dot {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-motion='on'] .sv-timeline__item::before,
    [data-motion='on'] .sv-timeline__dot {
      animation: none;
    }
  }

  .sv-timeline__time {
    display: block;
    color: var(--sv-ink-faint);
  }

  .sv-timeline__title {
    margin-top: 2px;
    font-size: 13px;
    font-weight: 600;
    color: var(--sv-ink);
  }

  .sv-timeline__body {
    margin-top: 3px;
    font-size: 12.5px;
    color: var(--sv-ink-soft);
  }

  .sv-timeline__actor {
    margin-top: var(--sv-s1);
    color: var(--sv-ink-faint);
  }

  .sv-timeline__day {
    padding: var(--sv-s3) 0 var(--sv-s2);
    font-size: 9.5px;
    color: var(--sv-ink-soft);
  }

  .sv-timeline__day:first-child {
    padding-top: 0;
  }
}
